+        let pref_branch = get_root_pref_branch()?;
+        unsafe { pref_branch.SetCharPref(EWS_SERVER_VERSIONS_PREF.as_ptr(), &*known_versions) }
+            .to_result()?;
+
+        Ok(())
+    }
+}
